#!/usr/bin/env node
// Task-local script: fetch contacts from the email API and save to contacts.txt
const fs = require('fs');

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';
const API_KEY = process.argv[2];
const USER_EMAIL = process.argv[3];
const OUT_FILE = process.argv[4] || 'contacts.txt';

if (!API_KEY || !USER_EMAIL) {
  console.error('Usage: node get_contacts.js <api-key> <user-email> [out-file]');
  process.exit(1);
}

async function main() {
  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': API_KEY,
      'X-User-Email': USER_EMAIL
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || `Failed to get contacts (HTTP ${response.status})`);
  }

  const contacts = data.contacts || [];
  const lines = contacts.map((c) => {
    const name = c.name || '';
    const email = c.email || '';
    return name ? `${name} <${email}>` : email;
  });

  fs.writeFileSync(OUT_FILE, lines.join('\n') + (lines.length ? '\n' : ''), 'utf8');

  console.log(JSON.stringify({ success: true, count: contacts.length, file: OUT_FILE, contacts }, null, 2));
}

main().catch((err) => {
  console.error(JSON.stringify({ success: false, error: err.message }, null, 2));
  process.exit(1);
});

// Task-local fallback for the registered email-contacts helper,
// which failed at runtime (missing 'minimist' dependency).
// Reproduces the documented contacts operation: GET {BASE}/contacts
// with X-API-Key and X-User-Email from the task-local credential record.
const fs = require("fs");

const BASE = process.env.EMAIL_API_BASE_URL || "https://agenskill-api.onrender.com";

async function main() {
  const creds = JSON.parse(fs.readFileSync("email_credentials.json", "utf8"));
  const apiKey = creds.account.api_key;
  const userEmail = creds.account.email;
  if (!apiKey || !userEmail) {
    throw new Error("Credential record missing api_key or email");
  }

  const res = await fetch(`${BASE}/contacts`, {
    headers: {
      "X-API-Key": apiKey,
      "X-User-Email": userEmail,
    },
  });
  const text = await res.text();
  if (!res.ok) {
    throw new Error(`Contacts request failed (${res.status}): ${text}`);
  }
  process.stdout.write(text);
}

main().catch((err) => {
  console.error(err && err.stack ? err.stack : String(err));
  process.exit(1);
});
